static int
GenICam_set_pixel_format(void *_self, uint32_t pixel_format)
{
    struct GenICam *self = cast(GenICam(), _self);
    
    ArvCamera *camera = (ArvCamera *) self->camera;
    GError *error = NULL;
    unsigned int state;
    uint16_t options;
    int ret = AAOS_OK;
    
    Pthread_mutex_lock(&self->_.d_state.mtx);
    state = self->_.d_state.state;
    options = self->_.d_state.options;
    if ((state&DETECTOR_STATE_MALFUNCTION) && !(options&DETECTOR_OPTION_IGNORE_DEVMAL)) {
        ret = AAOS_EDEVMAL;
        goto error;
    } else if ((state&DETECTOR_STATE_READING) || (state&DETECTOR_STATE_EXPOSING)) {
        if (options&DETECTOR_OPTION_NOWAIT) {
            ret = AAOS_EBUSY;
            goto error;
        }
        while ((state&DETECTOR_STATE_EXPOSING) || (state&DETECTOR_STATE_READING)) {
            Pthread_cond_wait(&self->_.d_state.cond, &self->_.d_state.mtx);
        }
    } else if (state&DETECTOR_STATE_UNINITIALIZED) {
        ret = AAOS_EUNINIT;
        goto error;
    } else if (state&DETECTOR_STATE_OFFLINE) {
        ret = AAOS_EPWROFF;
        goto error;
    }
    
    switch (pixel_format) {
        case DETECTOR_PIXEL_FORMAT_MONO_8:
            Pthread_mutex_lock(&self->mtx);
            arv_camera_set_pixel_format(camera, ARV_PIXEL_FORMAT_MONO_8, &error);
            Pthread_mutex_unlock(&self->mtx);
            break;
        case DETECTOR_PIXEL_FORMAT_MONO_10:
            Pthread_mutex_lock(&self->mtx);
            arv_camera_set_pixel_format(camera, ARV_PIXEL_FORMAT_MONO_10, &error);
            Pthread_mutex_unlock(&self->mtx);
            break;
        case DETECTOR_PIXEL_FORMAT_MONO_10_PACKED:
            Pthread_mutex_lock(&self->mtx);
            arv_camera_set_pixel_format(camera, ARV_PIXEL_FORMAT_MONO_10_PACKED, &error);
            Pthread_mutex_unlock(&self->mtx);
            break;
        case DETECTOR_PIXEL_FORMAT_MONO_12:
            Pthread_mutex_lock(&self->mtx);
            arv_camera_set_pixel_format(camera, ARV_PIXEL_FORMAT_MONO_12, &error);
            Pthread_mutex_unlock(&self->mtx);
            break;
        case DETECTOR_PIXEL_FORMAT_MONO_12_PACKED:
            Pthread_mutex_lock(&self->mtx);
            arv_camera_set_pixel_format(camera, ARV_PIXEL_FORMAT_MONO_12_PACKED, &error);
            Pthread_mutex_unlock(&self->mtx);
            break;
        case DETECTOR_PIXEL_FORMAT_MONO_14:
            Pthread_mutex_lock(&self->mtx);
            arv_camera_set_pixel_format(camera, ARV_PIXEL_FORMAT_MONO_14, &error);
            Pthread_mutex_unlock(&self->mtx);
            break;
        case DETECTOR_PIXEL_FORMAT_MONO_16:
            Pthread_mutex_lock(&self->mtx);
            arv_camera_set_pixel_format(camera, ARV_PIXEL_FORMAT_MONO_16, &error);
            Pthread_mutex_unlock(&self->mtx);
            break;
        case DETECTOR_PIXEL_FORMAT_RGB_24:
            Pthread_mutex_lock(&self->mtx);
            arv_camera_set_pixel_format(camera, ARV_PIXEL_FORMAT_RGB_8_PACKED, &error);
            Pthread_mutex_unlock(&self->mtx);
            break;
        case DETECTOR_PIXEL_FORMAT_YUV422:
            Pthread_mutex_lock(&self->mtx);
            arv_camera_set_pixel_format(camera, ARV_PIXEL_FORMAT_YUV_422_PACKED, &error);
            Pthread_mutex_unlock(&self->mtx);
            break;
        default:
            ret = AAOS_EINVAL;
            goto error;
            break;
    }
    
    if (error == NULL) {
        Pthread_rwlock_wrlock(&self->_.d_param.rwlock);
        self->_.d_param.pixel_format = pixel_format;
        Pthread_rwlock_unlock(&self->_.d_param.rwlock);
    } else {
        g_clear_error(&error);
        ret = AAOS_ERROR;
    }
    
error:
    Pthread_mutex_unlock(&self->_.d_state.mtx);
    return ret;
}

static int
GenICam_get_pixel_format(void *_self, uint32_t *pixel_format)
{
    struct GenICam *self = cast(GenICam(), _self);
    
    unsigned int state;
    uint16_t options;
    ArvCamera *camera = (ArvCamera *) self->camera;
    GError *error = NULL;
    int ret = AAOS_OK;
    gint x, y;
    
    Pthread_mutex_lock(&self->_.d_state.mtx);
    state = self->_.d_state.state;
    options = self->_.d_state.options;
    if ((state&DETECTOR_STATE_MALFUNCTION) && !(options&DETECTOR_OPTION_IGNORE_DEVMAL)) {
        ret = AAOS_EDEVMAL;
        goto error;
    } else if (state&DETECTOR_STATE_UNINITIALIZED) {
        ret = AAOS_EUNINIT;
        goto error;
    } else if (state&DETECTOR_STATE_OFFLINE) {
        ret = AAOS_EPWROFF;
        goto error;
    }
    Pthread_mutex_unlock(&self->_.d_state.mtx);
    
    Pthread_mutex_lock(&self->mtx);
    *pixel_format = arv_camera_get_pixel_format(camera, &error);
    Pthread_mutex_unlock(&self->mtx);
    if (error == NULL) {
        switch (*pixel_format) {
            case ARV_PIXEL_FORMAT_MONO_8:
                *pixel_format = DETECTOR_PIXEL_FORMAT_MONO_8;
                break;
            case ARV_PIXEL_FORMAT_MONO_10:
                *pixel_format = DETECTOR_PIXEL_FORMAT_MONO_10;
                break;
            case ARV_PIXEL_FORMAT_MONO_10_PACKED:
                *pixel_format = DETECTOR_PIXEL_FORMAT_MONO_10_PACKED;
                break;
            case ARV_PIXEL_FORMAT_MONO_12:
                *pixel_format = DETECTOR_PIXEL_FORMAT_MONO_12;
                break;
            case ARV_PIXEL_FORMAT_MONO_12_PACKED:
                *pixel_format = DETECTOR_PIXEL_FORMAT_MONO_12_PACKED;
                break;
            case ARV_PIXEL_FORMAT_MONO_14:
                *pixel_format = DETECTOR_PIXEL_FORMAT_MONO_14;
                break;
            case ARV_PIXEL_FORMAT_MONO_16:
                *pixel_format = DETECTOR_PIXEL_FORMAT_MONO_16;
                break;
            case ARV_PIXEL_FORMAT_RGB_8_PACKED:
                *pixel_format = DETECTOR_PIXEL_FORMAT_RGB_24;
                break;
            case ARV_PIXEL_FORMAT_YUV_422_PACKED:
                *pixel_format = DETECTOR_PIXEL_FORMAT_YUV422;
                break;
            default:
                *pixel_format = DETECTOR_PIXEL_FORMAT_UNKNOWN;
                break;
        }
    } else {
        Pthread_rwlock_rdlock(&self->_.d_param.rwlock);
        *pixel_format = self->_.d_param.pixel_format;
        Pthread_rwlock_unlock(&self->_.d_param.rwlock);
        g_clear_error(&error);
    }
    
    return ret;
    
error:
    Pthread_mutex_unlock(&self->_.d_state.mtx);
    return ret;
}


static int
GenICam_inspect(void *_self)
{
    struct GenICam *self = cast(GenICam(), _self);
    
    ArvCamera *camera = (ArvCamera *) self->camera;
    GError *error = NULL;
    int ret = AAOS_OK;
    
    Pthread_mutex_lock(&self->mtx);
    arv_camera_get_string(camera, "Vendor", &error);
    Pthread_mutex_unlock(&self->mtx);
    
    Pthread_mutex_lock(&self->_.d_state.mtx);
    if (error != NULL) {
        self->_.d_state.state |= DETECTOR_STATE_MALFUNCTION;
        ret = AAOS_EDEVMAL;
        g_clear_error(&error);
    } else {
        self->_.d_state.state &= ~DETECTOR_STATE_MALFUNCTION;
    }
    Pthread_mutex_unlock(&self->_.d_state.mtx);
    Pthread_cond_broadcast(&self->_.d_state.cond);
    
    return ret;
}

static int
GenICam_status_json(struct GenICam *self, void *res, size_t res_size, size_t *res_len)
{
    cJSON *root_json, *genicam_json;
    
    unsigned int state;
    uint16_t options;
    
    ArvCamera *camera = (ArvCamera *) self->camera;
    ArvDevice *device = arv_camera_get_device(camera);
    
    gint x, y, width, height;
    gint dx, dy;
    gint64 feature_64;
    
    ArvAcquisitionMode acquisition_mode;
    double frame_rate, exposure_time, gain;
    ArvPixelFormat pixel_format;
    ArvAuto auto_mode;
    const char *string;
    GError *error = NULL;
    
    Pthread_mutex_lock(&self->_.d_state.mtx);
    state = self->_.d_state.state;
    options = self->_.d_state.options;
    Pthread_mutex_unlock(&self->_.d_state.mtx);
    
    if ((root_json = cJSON_CreateObject()) == NULL) {
        return AAOS_ENOMEM;
    }
    
    cJSON_AddStringToObject(root_json, "name", self->_.name);
    if (self->_.description != NULL) {
        cJSON_AddStringToObject(root_json, "description", self->_.description);
    }
    
    if (state&DETECTOR_STATE_MALFUNCTION) {
        cJSON_AddStringToObject(root_json, "status", "MALFUNCTION");
    }
    switch (state&(~DETECTOR_STATE_MALFUNCTION)) {
        case DETECTOR_STATE_IDLE:
            cJSON_AddStringToObject(root_json, "state", "IDLE");
            break;
        case DETECTOR_STATE_OFFLINE:
            cJSON_AddStringToObject(root_json, "state", "OFFLINE");
            break;
        case DETECTOR_STATE_UNINITIALIZED:
            cJSON_AddStringToObject(root_json, "state", "UNINITIALIZED");
            break;
        case DETECTOR_STATE_EXPOSING:
            cJSON_AddStringToObject(root_json, "state", "EXPOSING");
            break;
        case DETECTOR_STATE_READING:
            cJSON_AddStringToObject(root_json, "state", "READING");
            break;
        default:
            break;
    }
    
    if (self->_.d_cap.offset_available) {
        Pthread_mutex_lock(&self->mtx);
        arv_camera_get_region(camera, &x, &y, &width, &height, &error);
        Pthread_mutex_unlock(&self->mtx);
        if (error == NULL) {
            cJSON_AddNumberToObject(root_json, "image_width", (double) width);
            cJSON_AddNumberToObject(root_json, "image_height", (double) height);
            cJSON_AddNumberToObject(root_json, "x_offset", (double) x);
            cJSON_AddNumberToObject(root_json, "y_offset", (double) y);
        } else {
            Pthread_rwlock_rdlock(&self->_.d_param.rwlock);
            cJSON_AddNumberToObject(root_json, "image_width", (double) self->_.d_param.image_width);
            cJSON_AddNumberToObject(root_json, "image_height", (double) self->_.d_param.image_height);
            cJSON_AddNumberToObject(root_json, "x_offset", (double) self->_.d_param.x_offset);
            cJSON_AddNumberToObject(root_json, "y_offset", (double) self->_.d_param.y_offset);
            Pthread_rwlock_unlock(&self->_.d_param.rwlock);
            g_clear_error(&error);
        }
    } else {
        cJSON_AddNumberToObject(root_json, "image_width", (double) self->_.d_cap.width);
        cJSON_AddNumberToObject(root_json, "image_height", (double) self->_.d_cap.height);
        cJSON_AddNumberToObject(root_json, "x_offset", (double) 0);
        cJSON_AddNumberToObject(root_json, "y_offset", (double) 0);
    }
    
    if (self->_.d_cap.binning_available) {
        Pthread_mutex_lock(&self->mtx);
        arv_camera_get_binning(camera, &dx, &dy, &error);
        Pthread_mutex_unlock(&self->mtx);
        if (error == NULL) {
            cJSON_AddNumberToObject(root_json, "x_binning", (double) dx);
            cJSON_AddNumberToObject(root_json, "y_binning", (double) dy);
        } else {
            Pthread_rwlock_rdlock(&self->_.d_param.rwlock);
            cJSON_AddNumberToObject(root_json, "x_binning", (double) self->_.d_param.x_binning);
            cJSON_AddNumberToObject(root_json, "y_binning", (double) self->_.d_param.y_binning);
            Pthread_rwlock_unlock(&self->_.d_param.rwlock);
            g_clear_error(&error);
        }
    }
    
    if (self->_.d_cap.capture_mode_available) {
        Pthread_mutex_lock(&self->mtx);
        acquisition_mode = arv_camera_get_acquisition_mode(camera, &error);
        Pthread_mutex_unlock(&self->mtx);
        if (error == NULL) {
            switch (acquisition_mode) {
                case ARV_ACQUISITION_MODE_SINGLE_FRAME:
                    cJSON_AddStringToObject(root_json, "capture_mode", "snapshot");
                    break;
                case ARV_ACQUISITION_MODE_MULTI_FRAME:
                    cJSON_AddStringToObject(root_json, "capture_mode", "multiframe");
                    break;
                case ARV_ACQUISITION_MODE_CONTINUOUS:
                    cJSON_AddStringToObject(root_json, "capture_mode", "video");
                    break;
                default:
                    break;
            }
        } else {
            Pthread_rwlock_rdlock(&self->_.d_param.rwlock);
            switch (self->_.d_param.capture_mode) {
                case DETECTOR_CAPTURE_MODE_SNAPSHOT:
                    cJSON_AddStringToObject(root_json, "capture_mode", "snapshot");
                    break;
                case DETECTOR_CAPTURE_MODE_MULTIFRAME:
                    cJSON_AddStringToObject(root_json, "capture_mode", "multiframe");
                    break;
                case DETECTOR_CAPTURE_MODE_VIDEO:
                    cJSON_AddStringToObject(root_json, "capture_mode", "video");
                    break;
                default:
                    break;
            }
            Pthread_rwlock_unlock(&self->_.d_param.rwlock);
            g_clear_error(&error);
        }
    }
    
    if (self->_.d_cap.frame_rate_available) {
        Pthread_mutex_lock(&self->mtx);
        frame_rate = arv_camera_get_frame_rate(camera, &error);
        Pthread_mutex_unlock(&self->mtx);
        if (error == NULL) {
            cJSON_AddNumberToObject(root_json, "frame_rate", frame_rate);
        } else {
            g_clear_error(&error);
            gint64 us_per_second;
            Pthread_mutex_lock(&self->mtx);
            us_per_second = arv_camera_get_integer(camera, "ProgFrameTimeAbs", &error);
            Pthread_mutex_unlock(&self->mtx);
            if (error == NULL) {
                cJSON_AddNumberToObject(root_json, "frame_rate", 1000000. / us_per_second);
            } else {
                g_clear_error(&error);
                Pthread_rwlock_rdlock(&self->_.d_param.rwlock);
                cJSON_AddNumberToObject(root_json, "frame_rate", self->_.d_param.frame_rate);
                Pthread_rwlock_unlock(&self->_.d_param.rwlock);
            }
        }
    }
    
    if (self->_.d_cap.exposure_time_available) {
        Pthread_mutex_lock(&self->mtx);
        exposure_time = arv_camera_get_exposure_time(camera, &error);
        Pthread_mutex_unlock(&self->mtx);
        if (error == NULL) {
            cJSON_AddNumberToObject(root_json, "exposure_time", exposure_time / 1000000.);
        } else {
            g_clear_error(&error);
            Pthread_mutex_lock(&self->mtx);
            exposure_time = arv_camera_get_integer(camera, "ExposureTimeRaw", &error);
            Pthread_mutex_unlock(&self->mtx);
            if (error == NULL) {
                cJSON_AddNumberToObject(root_json, "exposure_time", exposure_time / 1000000.);
            } else {
                g_clear_error(&error);
                Pthread_rwlock_rdlock(&self->_.d_param.rwlock);
                cJSON_AddNumberToObject(root_json, "exposure_time", self->_.d_param.exposure_time);
                Pthread_rwlock_unlock(&self->_.d_param.rwlock);
            }
        }
    }
    
    if (self->_.d_cap.auto_exposure_time_available) {
        Pthread_mutex_lock(&self->mtx);
        auto_mode = arv_camera_get_exposure_time_auto(camera, &error);
        Pthread_mutex_unlock(&self->mtx);
        if (error == NULL) {
            if (auto_mode == ARV_AUTO_OFF) {
                cJSON_AddBoolToObject(root_json, "auto_exposure_time_enable", false);
            } else {
                cJSON_AddBoolToObject(root_json, "auto_exposure_time_enable", true);
            }
        } else {
            Pthread_rwlock_rdlock(&self->_.d_param.rwlock);
            cJSON_AddBoolToObject(root_json, "auto_exposure_time_enable", self->_.d_param.auto_exposure_time_enable);
            Pthread_rwlock_unlock(&self->_.d_param.rwlock);
        }
    }
    
    if (self->_.d_cap.gain_available) {
        Pthread_mutex_lock(&self->mtx);
        gain = arv_camera_get_gain(camera, &error);
        Pthread_mutex_unlock(&self->mtx);
        if (error == NULL) {
            cJSON_AddNumberToObject(root_json, "gain", gain);
        } else {
            Pthread_rwlock_rdlock(&self->_.d_param.rwlock);
            cJSON_AddNumberToObject(root_json, "gain", self->_.d_param.gain);
            Pthread_rwlock_unlock(&self->_.d_param.rwlock);
            g_clear_error(&error);
        }
    }
    if (self->_.d_cap.auto_gain_available) {
        Pthread_mutex_lock(&self->mtx);
        auto_mode = arv_camera_get_gain_auto(camera, &error);
        Pthread_mutex_unlock(&self->mtx);
        if (error == NULL) {
            if (auto_mode == ARV_AUTO_OFF) {
                cJSON_AddBoolToObject(root_json, "auto_gain_enable", false);
            } else {
                cJSON_AddBoolToObject(root_json, "auto_gain_enable", true);
            }
        } else {
            Pthread_rwlock_rdlock(&self->_.d_param.rwlock);
            cJSON_AddBoolToObject(root_json, "auto_gain_enable", self->_.d_param.auto_gain_enable);
            Pthread_rwlock_unlock(&self->_.d_param.rwlock);
            g_clear_error(&error);
        }
    }
    
    if (self->_.d_cap.pixel_format_available) {
        Pthread_mutex_lock(&self->mtx);
        pixel_format = arv_camera_get_pixel_format(camera, &error);
        Pthread_mutex_unlock(&self->mtx);
        if (error == NULL) {
            switch (pixel_format) {
                case ARV_PIXEL_FORMAT_MONO_8:
                    cJSON_AddStringToObject(root_json, "pixel_format", "mono8");
                    break;
                case ARV_PIXEL_FORMAT_MONO_10:
                    cJSON_AddStringToObject(root_json, "pixel_format", "mono10");
                    break;
                case ARV_PIXEL_FORMAT_MONO_10_PACKED:
                    cJSON_AddStringToObject(root_json, "pixel_format", "mono10_packed");
                    break;
                case ARV_PIXEL_FORMAT_MONO_12:
                    cJSON_AddStringToObject(root_json, "pixel_format", "mono12");
                    break;
                case ARV_PIXEL_FORMAT_MONO_12_PACKED:
                    cJSON_AddStringToObject(root_json, "pixel_format", "mono12_packed");
                    break;
                case ARV_PIXEL_FORMAT_MONO_14:
                    cJSON_AddStringToObject(root_json, "pixel_format", "mono14");
                    break;
                case ARV_PIXEL_FORMAT_MONO_16:
                    cJSON_AddStringToObject(root_json, "pixel_format", "mono16");
                    break;
                case ARV_PIXEL_FORMAT_RGB_8_PACKED:
                    cJSON_AddStringToObject(root_json, "pixel_format", "rgb24");
                    break;
                case ARV_PIXEL_FORMAT_YUV_422_PACKED:
                    cJSON_AddStringToObject(root_json, "pixel_format", "yuv422");
                    break;
                default:
                    break;
            }
        } else {
            Pthread_rwlock_rdlock(&self->_.d_param.rwlock);
            switch (self->_.d_param.pixel_format) {
                case DETECTOR_PIXEL_FORMAT_MONO_8:
                    cJSON_AddStringToObject(root_json, "pixel_format", "mono8");
                    break;
                case DETECTOR_PIXEL_FORMAT_MONO_10:
                    cJSON_AddStringToObject(root_json, "pixel_format", "mono10");
                    break;
                case DETECTOR_PIXEL_FORMAT_MONO_10_PACKED:
                    cJSON_AddStringToObject(root_json, "pixel_format", "mono10_packed");
                    break;
                case DETECTOR_PIXEL_FORMAT_MONO_12:
                    cJSON_AddStringToObject(root_json, "pixel_format", "mono12");
                    break;
                case DETECTOR_PIXEL_FORMAT_MONO_12_PACKED:
                    cJSON_AddStringToObject(root_json, "pixel_format", "mono12_packed");
                    break;
                case DETECTOR_PIXEL_FORMAT_MONO_14:
                    cJSON_AddStringToObject(root_json, "pixel_format", "mono14");
                    break;
                case DETECTOR_PIXEL_FORMAT_MONO_14_PACKED:
                    cJSON_AddStringToObject(root_json, "pixel_format", "mono14_packed");
                    break;
                case DETECTOR_PIXEL_FORMAT_MONO_16:
                    cJSON_AddStringToObject(root_json, "pixel_format", "mono16");
                    break;
                case DETECTOR_PIXEL_FORMAT_MONO_18:
                    cJSON_AddStringToObject(root_json, "pixel_format", "mono18");
                    break;
                case DETECTOR_PIXEL_FORMAT_MONO_18_PACKED:
                    cJSON_AddStringToObject(root_json, "pixel_format", "mono18_packed");
                    break;
                case DETECTOR_PIXEL_FORMAT_MONO_24:
                    cJSON_AddStringToObject(root_json, "pixel_format", "mono24");
                    break;
                case DETECTOR_PIXEL_FORMAT_MONO_24_PACKED:
                    cJSON_AddStringToObject(root_json, "pixel_format", "mono24_packed");
                    break;
                case DETECTOR_PIXEL_FORMAT_MONO_32:
                    cJSON_AddStringToObject(root_json, "pixel_format", "mono32");
                    break;
                case DETECTOR_PIXEL_FORMAT_MONO_64:
                    cJSON_AddStringToObject(root_json, "pixel_format", "mono64");
                    break;
                case DETECTOR_PIXEL_FORMAT_RGB_24:
                    cJSON_AddStringToObject(root_json, "pixel_format", "rgb24");
                    break;
                case DETECTOR_PIXEL_FORMAT_YUV422:
                    cJSON_AddStringToObject(root_json, "pixel_format", "yuv422");
                    break;
                default:
                    break;
            }
            Pthread_rwlock_unlock(&self->_.d_param.rwlock);
            g_clear_error(&error);
        }
    } else {
        cJSON_AddStringToObject(root_json, "pixel_format", "mono16");
    }
    
    if (self->_.d_cap.trigger_available) {
        Pthread_rwlock_rdlock(&self->_.d_param.rwlock);
        switch (self->_.d_param.trigger_mode) {
            case DETECTOR_TRIGGER_MODE_DEFAULT:
                cJSON_AddStringToObject(root_json, "trigger_mode", "default");
                break;
            case DETECTOR_TRIGGER_MODE_SOFTWARE_EDGE:
                cJSON_AddStringToObject(root_json, "trigger_mode", "software_edge");
                break;
            case DETECTOR_TRIGGER_MODE_SOFTWARE_LEVEL:
                cJSON_AddStringToObject(root_json, "trigger_mode", "software_level");
                break;
            case DETECTOR_TRIGGER_MODE_HARDWARE_EDGE_FALL:
                cJSON_AddStringToObject(root_json, "trigger_mode", "edge_fall");
                break;
            case DETECTOR_TRIGGER_MODE_HARDWARE_EDGE_RISE:
                cJSON_AddStringToObject(root_json, "trigger_mode", "edge_rise");
                break;
            case DETECTOR_TRIGGER_MODE_HARDWARE_LEVEL_LOW:
                cJSON_AddStringToObject(root_json, "trigger_mode", "level_low");
                break;
            case DETECTOR_TRIGGER_MODE_HARDWARE_LEVEL_HIGH:
                cJSON_AddStringToObject(root_json, "trigger_mode", "level_high");
                break;
            default:
                break;
        }
        Pthread_rwlock_unlock(&self->_.d_param.rwlock);
    } else {
        cJSON_AddStringToObject(root_json, "trigger_mode", "default");
    }
    
    feature_64 = arv_device_get_integer_feature_value(device, "CurrentTemperature", &error);
    if (error == NULL) {
        if (feature_64 > 128) {
            cJSON_AddNumberToObject(root_json, "temperature", feature_64 - 255);
        } else {
            cJSON_AddNumberToObject(root_json, "temperature", feature_64 );
        }
    } else {
        g_clear_error(&error);
    }
    
    if ((genicam_json = cJSON_CreateObject()) == NULL) {
        cJSON_Delete(root_json);
        return AAOS_ENOMEM;
    }
    
    Pthread_mutex_lock(&self->mtx);
    string = arv_camera_get_vendor_name(camera, &error);
    Pthread_mutex_unlock(&self->mtx);
    if (error == NULL) {
        cJSON_AddStringToObject(genicam_json, "vendor", string);
    } else {
        g_clear_error(&error);
    }
    Pthread_mutex_lock(&self->mtx);
    string = arv_camera_get_model_name(camera, &error);
    Pthread_mutex_unlock(&self->mtx);
    if (error == NULL) {
        cJSON_AddStringToObject(genicam_json, "model", string);
    } else {
        g_clear_error(&error);
    }
    Pthread_mutex_lock(&self->mtx);
    string = arv_camera_get_device_id(camera, &error);
    Pthread_mutex_unlock(&self->mtx);
    if (error == NULL) {
        cJSON_AddStringToObject(genicam_json, "device_id", string);
    } else {
        g_clear_error(&error);
    }
    
    Pthread_mutex_lock(&self->mtx);
    string = arv_camera_get_string(camera, "DeviceUserID", &error);
    Pthread_mutex_unlock(&self->mtx);
    if (error == NULL) {
        cJSON_AddStringToObject(genicam_json, "name", string);
    } else {
        g_clear_error(&error);
    }
    
    Pthread_mutex_lock(&self->mtx);
    feature_64 = arv_camera_get_integer(camera, "GevCurrentIPAddress", &error);
    Pthread_mutex_unlock(&self->mtx);
    if (error == NULL) {
        unsigned int ip = (unsigned int) feature_64;
        char address[16];
        snprintf(address, 16, "%d.%d.%d.%d", (ip>>24)&0xFF, (ip>>16)&0xFF, (ip>>8)&0xFF, ip&0xFF);
        cJSON_AddStringToObject(genicam_json, "IP", address);
    } else {
        g_clear_error(&error);
    }
    
    Pthread_mutex_lock(&self->mtx);
    feature_64 = arv_camera_get_integer(camera, "GevCurrentSubnetMask", &error);
    Pthread_mutex_unlock(&self->mtx);
    if (error == NULL) {
        unsigned int mask = (unsigned int) feature_64;
        char subnet[16];
        snprintf(subnet, 16, "%d.%d.%d.%d", (mask>>24)&0xFF, (mask>>16)&0xFF, (mask>>8)&0xFF, mask&0xFF);
        cJSON_AddStringToObject(genicam_json, "mask", subnet);
    } else {
        g_clear_error(&error);
    }
    
    Pthread_mutex_lock(&self->mtx);
    feature_64 = arv_camera_get_integer(camera, "GevCurrentDefaultGateway", &error);
    Pthread_mutex_unlock(&self->mtx);
    if (error == NULL) {
        unsigned int gw = (unsigned int) feature_64;
        char gateway[16];
        snprintf(gateway, 16, "%d.%d.%d.%d", (gw>>24)&0xFF, (gw>>16)&0xFF, (gw>>8)&0xFF, gw&0xFF);
        cJSON_AddStringToObject(genicam_json, "gateway", gateway);
    } else {
        g_clear_error(&error);
    }
    
    cJSON_AddItemToObject(root_json, "genicam", genicam_json);
    
    cJSON_PrintPreallocated(root_json, res, (int) res_size, 1);
    cJSON_Delete(root_json);
    
    if (res_len != NULL) {
        *res_len = strlen((char *) res);
    }
    
    return AAOS_OK;
}

static int
GenICam_status(void *_self, void *res, size_t res_size, size_t *res_len)
{
    struct GenICam *self = cast(GenICam(), _self);
    
    int ret;
    
    ret = GenICam_status_json(self, res, res_size, res_len);
    
    return ret;
}

static int
GenICam_info_plain(struct GenICam *self, void *res, size_t res_size, size_t *res_len)
{
    ArvCamera *camera = (ArvCamera *) self->camera;
    GError *error = NULL;
    FILE *fp;
    int ret = AAOS_OK;
    
    fp = fmemopen(res, res_size, "w+");
    fprintf(fp, "Vendor:\t\t%s\n", arv_camera_get_vendor_name(camera, NULL));
    fprintf(fp, "Model:\t\t%s\n", arv_camera_get_model_name(camera, NULL));
    fprintf(fp, "Serial:\t\t%s\n", arv_camera_get_device_serial_number(camera, NULL));
    fprintf(fp, "DeviceID:\t%s\n", arv_camera_get_device_id(camera, NULL));
    fprintf(fp, "DeviceUserID:\t%s\n", arv_camera_get_device_id(camera, NULL));
    
    gint width, height;
    arv_camera_get_sensor_size(camera, &width, &height, NULL);
    fprintf(fp, "\nSensor format:\t%dx%d\n", width, height);

    gint x, y;
    arv_camera_get_region(camera, &x, &y, &width, &height, NULL);
    fprintf(fp, "Current region:\t[%d, %d, %d, %d]\n", x, y, width, height);
    gint min, max, increment;
    arv_camera_get_x_offset_bounds(camera, &min, &max, NULL);
    increment = arv_camera_get_x_offset_increment(camera, NULL);
    fprintf(fp, "X-Offset range:\t[%d, %d, %d]\n", min, max, increment);
    arv_camera_get_y_offset_bounds(camera, &min, &max, NULL);
    increment = arv_camera_get_y_offset_increment(camera, NULL);
    fprintf(fp, "Y-Offset range:\t[%d, %d, %d]\n", min, max, increment);
    arv_camera_get_width_bounds(camera, &min, &max, NULL);
    increment = arv_camera_get_width_increment(camera, NULL);
    fprintf(fp, "Width range:\t[%d, %d, %d]\n", min, max, increment);
    arv_camera_get_height_bounds(camera, &min, &max, NULL);
    increment = arv_camera_get_height_increment(camera, NULL);
    fprintf(fp, "Height range:\t[%d, %d, %d]\n", min, max, increment);
    
    guint n;
    const char **available_pixel_formats = arv_camera_dup_available_pixel_formats_as_display_names(camera, &n, NULL);
    if (available_pixel_formats != NULL) {
        guint i;
        fprintf(fp, "\nPixel format:\t%s\n", available_pixel_formats[0]);
        for (i = 1; i < n; i++) {
            fprintf(fp, "\t\t%s\n", available_pixel_formats[i]);
        }
        g_clear_pointer (&available_pixel_formats, g_free);
    } else {
        fprintf(fp, "\nPixel format:\tnot available\n");
    }
    fprintf(fp, "Current:\t%s\n", arv_camera_get_pixel_format_as_string(camera, NULL));

    if (arv_camera_is_frame_rate_available(camera, NULL)) {
        fprintf(fp, "\nFramerate:\tavailable\n");
        double min = 0., max = 0., frame_rate = 0.;
        arv_camera_get_frame_rate_bounds(camera, &min, &max, NULL);
        fprintf(fp, "Range:\t\t[%.3f, %.3f] Hz\n", min, max);
        frame_rate = arv_camera_get_frame_rate(camera, NULL);
        fprintf(fp, "Current:\t%.6f Hz\n", frame_rate);
    } else {
        fprintf(fp, "\nFramerate:\tnot available\n");
    }
                
    if (arv_camera_is_exposure_time_available(camera, NULL)) {
        fprintf(fp, "\nExposureTime:\tavailable\n");
        double min = 0., max = 0., exposure_time = 0.;
        arv_camera_get_exposure_time_bounds(camera, &min, &max, NULL);
        fprintf(fp, "Range:\t\t[%.0f, %.0f] us\n", min, max);
        exposure_time = arv_camera_get_exposure_time(camera, NULL);
        fprintf(fp, "Current:\t%.0f us\n", exposure_time);
    } else {
        fprintf(fp, "\nExposureTime:\tnot available\n");
    }

    if (arv_camera_is_gain_available(camera, NULL)) {
        fprintf(fp, "\nGain:\t\tavailable\n");
        double min = 0., max = 0., gain = 0.;
        arv_camera_get_gain_bounds(camera, &min, &max, NULL);
        fprintf(fp, "Range:\t\t[%.2f, %.2f] e-/ADU\n", min, max);
        gain = arv_camera_get_gain(camera, NULL);
        fprintf(fp, "Current:\t%.2f e-/ADU\n", gain);
    } else {
        fprintf(fp, "\nGain\t:\tnot available\n");
    }
    
    if (arv_camera_is_binning_available(camera, NULL)) {
        fprintf(fp, "\nBinning:\tavailable\n");
        gint min = 0, max = 0, increment = 0, x_binning = 0, y_binning  = 0;
        arv_camera_get_x_binning_bounds(camera, &min, &max, NULL);
        increment = arv_camera_get_x_binning_increment(camera, NULL);
        fprintf(fp, "Range:\t\thorizontal %d, %d, %d\n", min, max, increment);
        arv_camera_get_y_binning_bounds(camera, &min, &max, NULL);
        increment = arv_camera_get_y_binning_increment(camera, NULL);
        fprintf(fp, "Range:\t\tvertical   %d, %d, %d\n", min, max, increment);
        arv_camera_get_binning(camera, &x_binning, &y_binning, NULL);
        fprintf(fp, "Current:\t%dx%d\n", x_binning, y_binning);
    } else {
        fprintf(fp, "\nExposureTime:\tnot available\n");
    }

    fclose(fp);
    if (res_len != NULL) {
        *res_len = strlen(res) + 1;
    }
    return ret;
}

static int
GenICam_info_json(struct GenICam *self, void *res, size_t res_size, size_t *res_len)
{
    ArvCamera *camera = (ArvCamera *) self->camera;
    gint x, y, width, height;
    gint dx, dy;
    gboolean b;
    ArvAcquisitionMode acquisition_mode;
    double frame_rate, exposure_time, gain;
    ArvPixelFormat pixel_format;
    ArvAuto auto_mode;
    const char *string;
    const char **strings;
    double d_min, d_max;
    gint i_min, i_max;
    gint64 l_min, l_max;
    guint i, n_values;
    gint64 *l_values;
    GError *error = NULL;
    unsigned int state;
    uint16_t options;
    cJSON *root_json, *capability_json, *array_json;
    
    Pthread_mutex_lock(&self->_.d_state.mtx);
    state = self->_.d_state.state;
    options = self->_.d_state.options;
    Pthread_mutex_unlock(&self->_.d_state.mtx);
    

    if ((root_json = cJSON_CreateObject()) == NULL) {
        return AAOS_ENOMEM;
    }
    
    cJSON_AddStringToObject(root_json, "name", self->_.name);
    if (self->_.description != NULL) {
        cJSON_AddStringToObject(root_json, "description", self->_.description);
    }
    
    if ((capability_json = cJSON_CreateObject()) == NULL) {
        cJSON_Delete(root_json);
        return AAOS_ENOMEM;
    }
    
    cJSON_AddItemToObject(root_json, "capability", capability_json);
    
    Pthread_mutex_lock(&self->mtx);
    arv_camera_get_sensor_size(camera, &width, &height, &error);
    Pthread_mutex_unlock(&self->mtx);
    if (error == NULL) {
        cJSON_AddNumberToObject(capability_json, "width", width);
        cJSON_AddNumberToObject(capability_json, "height", height);
    } else {
        g_clear_error(&error);
        cJSON_AddNumberToObject(capability_json, "width", self->_.d_cap.width);
        cJSON_AddNumberToObject(capability_json, "height", self->_.d_cap.height);
    }
    
    Pthread_mutex_lock(&self->mtx);
    b = arv_camera_is_binning_available(camera, &error);
    Pthread_mutex_unlock(&self->mtx);
    if (error == NULL) {
        if (b) {
            cJSON_AddBoolToObject(capability_json, "binning_available", true);
            gint min_, max_;
            Pthread_mutex_lock(&self->mtx);
            arv_camera_get_x_binning_bounds(camera, &min_, &max_, &error);
            Pthread_mutex_unlock(&self->mtx);
            if (error == NULL) {
                cJSON_AddNumberToObject(capability_json, "x_binning_min", min_);
                cJSON_AddNumberToObject(capability_json, "x_binning_max", max_);
            } else {
                g_clear_error(&error);
                Pthread_mutex_lock(&self->mtx);
                l_values = arv_camera_dup_available_enumerations(camera, "BinningHorizontal", &n_values, &error);
                Pthread_mutex_unlock(&self->mtx);
                if (error == NULL) {
                    array_json = cJSON_CreateArray();
                    for (i = 0; i < n_values; i++) {
                        cJSON_AddItemToArray(array_json, cJSON_CreateNumber((double) l_values[i]));
                    }
                    cJSON_AddItemToObject(capability_json, "x_binning_array", array_json);
                    g_free(l_values);
                } else {
                    if (self->_.d_cap.x_binning_array == NULL) {
                        cJSON_AddNumberToObject(capability_json, "x_binning_min", self->_.d_cap.x_binning_min);
                        cJSON_AddNumberToObject(capability_json, "x_binning_max", self->_.d_cap.x_binning_max);
                    } else {
                        array_json = cJSON_CreateArray();
                        for (i = 0; i < self->_.d_cap.n_x_binning; i++) {
                            cJSON_AddItemToArray(array_json, cJSON_CreateNumber((double) self->_.d_cap.x_binning_array[i]));
                        }
                        cJSON_AddItemToObject(capability_json, "x_binning_array", array_json);
                    }
                }
            }
            Pthread_mutex_lock(&self->mtx);
            arv_camera_get_y_binning_bounds(camera, &min_, &max_, &error);
            Pthread_mutex_unlock(&self->mtx);
            if (error == NULL) {
                cJSON_AddNumberToObject(capability_json, "y_binning_min", min_);
                cJSON_AddNumberToObject(capability_json, "y_binning_max", max_);
            } else {
                g_clear_error(&error);
                Pthread_mutex_lock(&self->mtx);
                l_values = arv_camera_dup_available_enumerations(camera, "BinningVertical", &n_values, &error);
                Pthread_mutex_unlock(&self->mtx);
                if (error == NULL) {
                    array_json = cJSON_CreateArray();
                    for (i = 0; i < n_values; i++) {
                        cJSON_AddItemToArray(array_json, cJSON_CreateNumber((double) l_values[i]));
                    }
                    cJSON_AddItemToObject(capability_json, "y_binning_array", array_json);
                    g_free(l_values);
                } else {
                    if (self->_.d_cap.y_binning_array == NULL) {
                        cJSON_AddNumberToObject(capability_json, "y_binning_min", self->_.d_cap.y_binning_min);
                        cJSON_AddNumberToObject(capability_json, "y_binning_max", self->_.d_cap.y_binning_max);
                    } else {
                        array_json = cJSON_CreateArray();
                        for (i = 0; i < self->_.d_cap.n_y_binning; i++) {
                            cJSON_AddItemToArray(array_json, cJSON_CreateNumber((double) self->_.d_cap.y_binning_array[i]));
                        }
                        cJSON_AddItemToObject(capability_json, "y_binning_array", array_json);
                    }
                }
            }
        } else {
            cJSON_AddBoolToObject(capability_json, "binning_available", false);
        }
    } else {
        g_clear_error(&error);
        if (self->_.d_cap.binning_available) {
            cJSON_AddBoolToObject(capability_json, "binning_available", true);
            if (self->_.d_cap.x_binning_array == NULL) {
                cJSON_AddNumberToObject(capability_json, "x_binning_min", self->_.d_cap.x_binning_min);
                cJSON_AddNumberToObject(capability_json, "x_binning_max", self->_.d_cap.x_binning_max);
            } else {
                array_json = cJSON_CreateArray();
                for (i = 0; i < self->_.d_cap.n_x_binning; i++) {
                    cJSON_AddItemToArray(array_json, cJSON_CreateNumber((double) self->_.d_cap.x_binning_array[i]));
                }
                cJSON_AddItemToObject(capability_json, "x_binning_array", array_json);
            }
            if (self->_.d_cap.y_binning_array == NULL) {
                cJSON_AddNumberToObject(capability_json, "y_binning_min", self->_.d_cap.y_binning_min);
                cJSON_AddNumberToObject(capability_json, "y_binning_max", self->_.d_cap.y_binning_max);
            } else {
                array_json = cJSON_CreateArray();
                for (i = 0; i < self->_.d_cap.n_y_binning; i++) {
                    cJSON_AddItemToArray(array_json, cJSON_CreateNumber((double) self->_.d_cap.y_binning_array[i]));
                }
                cJSON_AddItemToObject(capability_json, "y_binning_array", array_json);
            }
        } else {
            cJSON_AddBoolToObject(capability_json, "binning_available", false);
        }
    }
    
    cJSON_AddBoolToObject(capability_json, "capture_mode_available", true);
    Pthread_mutex_lock(&self->mtx);
    strings = arv_camera_dup_available_enumerations_as_display_names(camera, "AcquisitionMode", &n_values, &error);
    Pthread_mutex_unlock(&self->mtx);
    if (error == NULL) {
        if ((array_json = cJSON_CreateArray()) == NULL) {
            cJSON_Delete(capability_json);
            return AAOS_ENOMEM;
        }
        for (i = 0; i < n_values; i++) {
            if (strcmp(strings[i], "Continuous") == 0) {
                cJSON_AddItemToArray(array_json, cJSON_CreateString("video"));
            } else if (strcmp(strings[i], "SingleFrame") == 0) {
                cJSON_AddItemToArray(array_json, cJSON_CreateString("snapshot"));
            } else if (strcmp(strings[i], "MultiFrame") == 0) {
                cJSON_AddItemToArray(array_json, cJSON_CreateString("multiframe"));
            }
        }
        cJSON_AddItemToObject(capability_json, "capture_mode", array_json);
        g_free(strings);
    } else {
        g_clear_error(&error);
        if ((array_json = cJSON_CreateArray()) == NULL) {
            cJSON_Delete(capability_json);
            return AAOS_ENOMEM;
        }
        for (i = 0; i < self->_.d_cap.n_capture_mode; i++) {
            switch (self->_.d_cap.capture_mode_array[i]) {
                case DETECTOR_CAPTURE_MODE_SNAPSHOT:
                    cJSON_AddItemToArray(array_json, cJSON_CreateString("snapshot"));
                    break;
                case DETECTOR_CAPTURE_MODE_MULTIFRAME:
                    cJSON_AddItemToArray(array_json, cJSON_CreateString("multiframe"));
                    break;
                case DETECTOR_CAPTURE_MODE_VIDEO:
                    cJSON_AddItemToArray(array_json, cJSON_CreateString("video"));
                    break;
                default:
                    break;
            }
        }
        cJSON_AddItemToObject(capability_json, "capture_mode", array_json);
    }
    
    Pthread_mutex_lock(&self->mtx);
    b = arv_camera_is_exposure_auto_available(camera, &error);
    Pthread_mutex_unlock(&self->mtx);
    if (error == NULL) {
        cJSON_AddBoolToObject(capability_json, "auto_exposure_time_available", b);
    } else {
        g_clear_error(&error);
        cJSON_AddBoolToObject(capability_json, "auto_exposure_time_available", self->_.d_cap.auto_exposure_time_available);
    }
    
    Pthread_mutex_lock(&self->mtx);
    b = arv_camera_is_exposure_time_available(camera, &error);
    Pthread_mutex_unlock(&self->mtx);
    if (error == NULL) {
        cJSON_AddBoolToObject(capability_json, "auto_exposure_time_available", b);
    } else {
        g_clear_error(&error);
        Pthread_mutex_lock(&self->mtx);
        b = arv_camera_is_feature_available(camera, "ExposureTimeRaw", &error);
        Pthread_mutex_unlock(&self->mtx);
        if (error == NULL) {
            cJSON_AddBoolToObject(capability_json, "auto_exposure_time_available", b);
        } else {
            g_clear_error(&error);
            cJSON_AddBoolToObject(capability_json, "auto_exposure_time_available", self->_.d_cap.exposure_time_available);
        }
    }
    Pthread_mutex_lock(&self->mtx);
    arv_camera_get_exposure_time_bounds(camera, &d_min, &d_max, &error);
    Pthread_mutex_unlock(&self->mtx);
    if (error == NULL) {
        cJSON_AddNumberToObject(capability_json, "exposure_time_min", d_min / 1000000.);
        cJSON_AddNumberToObject(capability_json, "exposure_time_max", d_max / 1000000.);
    } else {
        g_clear_error(&error);
        Pthread_mutex_lock(&self->mtx);
        arv_camera_get_float_bounds(camera, "ExposureTimeRaw", &d_min, &d_max, &error);
        Pthread_mutex_unlock(&self->mtx);
        if (error == NULL) {
            cJSON_AddNumberToObject(capability_json, "exposure_time_min", d_min / 1000000.);
            cJSON_AddNumberToObject(capability_json, "exposure_time_max", d_max / 1000000.);
        } else {
            g_clear_error(&error);
            cJSON_AddNumberToObject(capability_json, "exposure_time_min", self->_.d_cap.exposure_time_min);
            cJSON_AddNumberToObject(capability_json, "exposure_time_max", self->_.d_cap.exposure_time_max);
        }
    }
    
    cJSON_AddBoolToObject(capability_json, "auto_frame_rate_available", false);
    Pthread_mutex_lock(&self->mtx);
    arv_camera_get_frame_rate_bounds(camera, &d_min, &d_max, &error);
    Pthread_mutex_unlock(&self->mtx);
    if (error == NULL) {
        cJSON_AddNumberToObject(capability_json, "frame_rate_min", d_min);
        cJSON_AddNumberToObject(capability_json, "frame_rate_max", d_max);
    } else {
        g_clear_error(&error);
        Pthread_mutex_lock(&self->mtx);
        arv_camera_get_integer_bounds(camera, "ProgFrameTimeEnable", &l_min, &l_max, &error);
        Pthread_mutex_unlock(&self->mtx);
        if (error == NULL) {
            cJSON_AddNumberToObject(capability_json, "frame_rate_min", 1000000. / l_max);
            cJSON_AddNumberToObject(capability_json, "frame_rate_max", 1000000. / l_min);
        } else {
            g_clear_error(&error);
            cJSON_AddNumberToObject(capability_json, "frame_rate_min", self->_.d_cap.frame_rate_min);
            cJSON_AddNumberToObject(capability_json, "frame_rate_max", self->_.d_cap.frame_rate_max);
        }
    }
    
    Pthread_mutex_lock(&self->mtx);
    b = arv_camera_is_gain_auto_available(camera, &error);
    Pthread_mutex_unlock(&self->mtx);
    if (error == NULL) {
        cJSON_AddBoolToObject(capability_json, "auto_gain_available", b);
    } else {
        g_clear_error(&error);
        cJSON_AddBoolToObject(capability_json, "auto_gain_available", self->_.d_cap.auto_gain_available);
    }
    Pthread_mutex_lock(&self->mtx);
    arv_camera_get_gain_bounds(camera, &d_min, &d_max, &error);
    Pthread_mutex_unlock(&self->mtx);
    if (error == NULL) {
        cJSON_AddNumberToObject(capability_json, "gain_min", d_min);
        cJSON_AddNumberToObject(capability_json, "gain_max", d_max);
    } else {
        cJSON_AddNumberToObject(capability_json, "gain_min", self->_.d_cap.gain_min);
        cJSON_AddNumberToObject(capability_json, "gain_min", self->_.d_cap.gain_min);
    }
    
    Pthread_mutex_lock(&self->mtx);
    l_values = arv_camera_dup_available_pixel_formats(camera, &n_values, &error);
    Pthread_mutex_unlock(&self->mtx);
    if ((array_json = cJSON_CreateArray()) == NULL) {
        cJSON_Delete(root_json);
        return AAOS_ENOMEM;
    }
    if (error == NULL) {
        for (i = 0; i < n_values; i++) {
            switch (l_values[i]) {
                case ARV_PIXEL_FORMAT_MONO_8:
                    cJSON_AddItemToArray(array_json, cJSON_CreateString("mono8"));
                    break;
                case ARV_PIXEL_FORMAT_MONO_10:
                    cJSON_AddItemToArray(array_json, cJSON_CreateString("mono10"));
                    break;
                case ARV_PIXEL_FORMAT_MONO_10_PACKED:
                    cJSON_AddItemToArray(array_json, cJSON_CreateString("mono10_packed"));
                    break;
                case ARV_PIXEL_FORMAT_MONO_12:
                    cJSON_AddItemToArray(array_json, cJSON_CreateString("mono12"));
                    break;
                case ARV_PIXEL_FORMAT_MONO_12_PACKED:
                    cJSON_AddItemToArray(array_json, cJSON_CreateString("mono12_packed"));
                    break;
                case ARV_PIXEL_FORMAT_MONO_14:
                    cJSON_AddItemToArray(array_json, cJSON_CreateString("mono14"));
                    break;
                case ARV_PIXEL_FORMAT_MONO_16:
                    cJSON_AddItemToArray(array_json, cJSON_CreateString("mono16"));
                    break;
                case ARV_PIXEL_FORMAT_RGB_8_PACKED:
                    cJSON_AddItemToArray(array_json, cJSON_CreateString("rgb24"));
                    break;
                case ARV_PIXEL_FORMAT_YUV_422_PACKED:
                    cJSON_AddItemToArray(array_json, cJSON_CreateString("yuv422"));
                    break;
                default:
                    break;
            }
        }
        g_free(l_values);
        cJSON_AddItemToObject(capability_json, "pixel_format", array_json);
    } else {
        for (i = 0; i < self->_.d_cap.n_pixel_format; i++) {
            switch (self->_.d_cap.pixel_format_array[i]) {
                case DETECTOR_PIXEL_FORMAT_MONO_8:
                    cJSON_AddItemToArray(array_json, cJSON_CreateString("mono8"));
                    break;
                case DETECTOR_PIXEL_FORMAT_MONO_10:
                    cJSON_AddItemToArray(array_json, cJSON_CreateString("mono10"));
                    break;
                case DETECTOR_PIXEL_FORMAT_MONO_10_PACKED:
                    cJSON_AddItemToArray(array_json, cJSON_CreateString("mono10_packed"));
                    break;
                case DETECTOR_PIXEL_FORMAT_MONO_12:
                    cJSON_AddItemToArray(array_json, cJSON_CreateString("mono12"));
                    break;
                case DETECTOR_PIXEL_FORMAT_MONO_12_PACKED:
                    cJSON_AddItemToArray(array_json, cJSON_CreateString("mono12_packed"));
                    break;
                case DETECTOR_PIXEL_FORMAT_MONO_14:
                    cJSON_AddItemToArray(array_json, cJSON_CreateString("mono14"));
                    break;
                case DETECTOR_PIXEL_FORMAT_MONO_14_PACKED:
                    cJSON_AddItemToArray(array_json, cJSON_CreateString("mono14_packed"));
                    break;
                case DETECTOR_PIXEL_FORMAT_MONO_16:
                    cJSON_AddItemToArray(array_json, cJSON_CreateString("mono16"));
                    break;
                case DETECTOR_PIXEL_FORMAT_MONO_18:
                    cJSON_AddItemToArray(array_json, cJSON_CreateString("mono18"));
                    break;
                case DETECTOR_PIXEL_FORMAT_MONO_18_PACKED:
                    cJSON_AddItemToArray(array_json, cJSON_CreateString("mono18_packed"));
                    break;
                case DETECTOR_PIXEL_FORMAT_MONO_24:
                    cJSON_AddItemToArray(array_json, cJSON_CreateString("mono24"));
                    break;
                case DETECTOR_PIXEL_FORMAT_MONO_24_PACKED:
                    cJSON_AddItemToArray(array_json, cJSON_CreateString("mono24_packed"));
                    break;
                case DETECTOR_PIXEL_FORMAT_MONO_32:
                    cJSON_AddStringToObject(capability_json, "pixel_format", "mono32");
                    break;
                case DETECTOR_PIXEL_FORMAT_MONO_64:
                    cJSON_AddItemToArray(array_json, cJSON_CreateString("mono64"));
                    break;
                case DETECTOR_PIXEL_FORMAT_RGB_24:
                    cJSON_AddItemToArray(array_json, cJSON_CreateString("rgb24"));
                    break;
                case DETECTOR_PIXEL_FORMAT_YUV422:
                    cJSON_AddItemToArray(array_json, cJSON_CreateString("yuv422"));
                    break;
                default:
                    break;
            }
        }
        cJSON_AddItemToObject(capability_json, "pixel_format", array_json);
    }
    
    cJSON_AddBoolToObject(capability_json, "offset_available", true);
    Pthread_mutex_lock(&self->mtx);
    arv_camera_get_x_offset_bounds(camera, &i_min, &i_max, &error);
    Pthread_mutex_unlock(&self->mtx);
    if (error == NULL) {
        cJSON_AddNumberToObject(capability_json, "x_offset_min", i_min);
        cJSON_AddNumberToObject(capability_json, "x_offset_max", i_max);
    } else {
        cJSON_AddNumberToObject(capability_json, "x_offset_min", self->_.d_cap.x_offset_min);
        cJSON_AddNumberToObject(capability_json, "x_offset_max", self->_.d_cap.x_offset_max);
    }
    Pthread_mutex_lock(&self->mtx);
    arv_camera_get_y_offset_bounds(camera, &i_min, &i_max, &error);
    Pthread_mutex_unlock(&self->mtx);
    if (error == NULL) {
        cJSON_AddNumberToObject(capability_json, "y_offset_min", i_min);
        cJSON_AddNumberToObject(capability_json, "y_offset_max", i_max);
    } else {
        cJSON_AddNumberToObject(capability_json, "y_offset_min", self->_.d_cap.y_offset_min);
        cJSON_AddNumberToObject(capability_json, "y_offset_max", self->_.d_cap.y_offset_max);
    }
    Pthread_mutex_lock(&self->mtx);
    arv_camera_get_width_bounds(camera, &i_min, &i_max, &error);
    Pthread_mutex_unlock(&self->mtx);
    if (error == NULL) {
        cJSON_AddNumberToObject(capability_json, "image_width_min", i_min);
        cJSON_AddNumberToObject(capability_json, "image_width_max", i_max);
    } else {
        cJSON_AddNumberToObject(capability_json, "image_width_min", self->_.d_cap.image_width_min);
        cJSON_AddNumberToObject(capability_json, "image_width_max", self->_.d_cap.image_width_max);
    }
    Pthread_mutex_lock(&self->mtx);
    arv_camera_get_height_bounds(camera, &i_min, &i_max, &error);
    Pthread_mutex_unlock(&self->mtx);
    if (error == NULL) {
        cJSON_AddNumberToObject(capability_json, "image_height_min", i_min);
        cJSON_AddNumberToObject(capability_json, "image_height_max", i_max);
    } else {
        cJSON_AddNumberToObject(capability_json, "image_height_min", self->_.d_cap.image_height_min);
        cJSON_AddNumberToObject(capability_json, "image_height_max", self->_.d_cap.image_height_max);
    }
    
    cJSON_AddBoolToObject(capability_json, "cooling_available", false);
    cJSON_AddBoolToObject(capability_json, "auto_cooling_available", false);
    cJSON_AddBoolToObject(capability_json, "overscan_available", false);
    cJSON_AddBoolToObject(capability_json, "readout_rate_available", false);
    cJSON_AddBoolToObject(capability_json, "trigger_mode_available", false);
    
    
    cJSON_PrintPreallocated(root_json, res, (int) res_size, 1);
    cJSON_Delete(root_json);
    if (res_len != NULL) {
        *res_len = strlen((char *) res);
    }
    
    return AAOS_OK;
}

static int
GenICam_info(void *_self, void *res, size_t res_size, size_t *res_len)
{
    struct GenICam *self = cast(GenICam(), _self);
    
    int ret;
    
    ret = GenICam_info_json(self, res, res_size, res_len);
    
    return ret;
}

static int
GenICam_stop(void *_self)
{
    struct GenICam *self = cast(GenICam(), _self);
    
    unsigned int state;
    uint16_t options;

    Pthread_mutex_lock(&self->_.d_state.mtx);
    state = self->_.d_state.state;
    options = self->_.d_state.options;
    if (state&DETECTOR_STATE_MALFUNCTION && !(options&DETECTOR_OPTION_IGNORE_DEVMAL)) {
        Pthread_mutex_unlock(&self->_.d_state.mtx);
        return AAOS_EDEVMAL;
    }
    if ((state&DETECTOR_STATE_EXPOSING) || (state&DETECTOR_STATE_READING)) {
        Pthread_mutex_unlock(&self->_.d_state.mtx);
        Pthread_mutex_lock(&self->_.d_exp.mtx);
        self->_.d_exp.stop_flag = true;
        while (self->_.d_exp.stop_flag) {
            Pthread_cond_wait(&self->_.d_exp.cond, &self->_.d_exp.mtx);
        }
        Pthread_mutex_unlock(&self->_.d_exp.mtx);
    } else {
        Pthread_mutex_unlock(&self->_.d_state.mtx);
    }
    
    return AAOS_OK;
}

static int
GenICam_abort(void *_self)
{
    struct GenICam *self = cast(GenICam(), _self);
    
    ArvCamera *camera = (ArvCamera *) self->camera;
    GError *error = NULL;
    unsigned int state;
    uint16_t options;
    int ret = AAOS_OK;
    

    Pthread_mutex_lock(&self->_.d_state.mtx);
    state = self->_.d_state.state;
    options = self->_.d_state.options;
    if (state&DETECTOR_STATE_MALFUNCTION && !(options&DETECTOR_OPTION_IGNORE_DEVMAL)) {
        goto error;
    }
    if ((state&DETECTOR_STATE_EXPOSING) || (state&DETECTOR_STATE_READING)) {
        Pthread_mutex_lock(&self->mtx);
        arv_camera_abort_acquisition(camera, &error);
        Pthread_mutex_unlock(&self->mtx);
    }
    if (error != NULL) {
#ifdef DEBUG
        fprintf(stderr, "%s %s %d --- arv_camera_abort_acquisition error: %s\n", __FILE__, __func__, __LINE__ - 5, error->message);
#endif
        ret = AAOS_ERROR;
        g_clear_error(&error);
    }
error:
    Pthread_mutex_unlock(&self->_.d_state.mtx);
    return ret;
}

static const void *_genicam_virtual_table;

static void
genicam_virtual_table_destroy(void)
{
    delete((void *) _genicam_virtual_table);
}

static void
genicam_virtual_table_initialize(void)
{
    _genicam_virtual_table = new(__DetectorVirtualTable(),
                                 __detector_init, "init", GenICam_init,
                                 __detector_status, "status", GenICam_status,
                                 __detector_info, "info", GenICam_info,
                                 __detector_power_on, "power_on", GenICam_power_on,
                                 __detector_power_off, "power_off", GenICam_power_off,
                                 __detector_expose, "expose", GenICam_expose,
                                 __detector_set_binning, "set_binning", GenICam_set_binning,
                                 __detector_get_binning, "get_binning", GenICam_get_binning,
                                 __detector_set_exposure_time, "set_exposure_time", GenICam_set_exposure_time,
                                 __detector_get_exposure_time, "get_exposure_time", GenICam_get_exposure_time,
                                 __detector_set_frame_rate, "set_frame_rate", GenICam_set_frame_rate,
                                 __detector_get_frame_rate, "get_frame_rate", GenICam_get_frame_rate,
                                 __detector_set_gain, "set_gain", GenICam_set_gain,
                                 __detector_get_gain, "get_gain", GenICam_get_gain,
                                 __detector_set_region, "set_region", GenICam_set_region,
                                 __detector_get_region, "get_region", GenICam_get_region,
                                 __detector_set_capture_mode, "set_capture_mode", GenICam_set_capture_mode,
                                 __detector_get_capture_mode, "get_capture_mode", GenICam_get_capture_mode,
                                 __detector_set_pixel_format, "set_pixel_format", GenICam_set_pixel_format,
                                 __detector_get_pixel_format, "get_pixel_format", GenICam_get_pixel_format,
                                 __detector_raw, "raw", GenICam_raw,
                                 __detector_inspect, "inspect", GenICam_inspect,
                                 __detector_wait_for_completion, "wait_for_completion", GenICam_wait_for_last_completion,
                                 __detector_stop, "stop", GenICam_stop,
                                 __detector_abort, "abotr", GenICam_abort,
                                 
                                 (void *)0);
#ifndef _USE_COMPILER_ATTRIBUTION_
    atexit(genicam_virtual_table_destroy);
#endif
}

static const void *
genicam_virtual_table(void)
{
#ifndef _USE_COMPILER_ATTRIBUTION_
    static pthread_once_t once_control = PTHREAD_ONCE_INIT;
    Pthread_once(&once_control, genicam_virtual_table_initialize);
#endif
    
    return _genicam_virtual_table;
}
#endif

